{
  "name": "MC2000电动显微镜载物台控制器",
  "name_en": "MC2000 motorized microscope stage controller",
  "manufacturer": "",
  "description": "MC2000是一类用于控制显微镜电动载物台或多轴位移台的运动控制设备，通常支持X/Y/Z通道的位置读取、目标位置移动以及摇杆手动控制。在实验室中可用于显微成像时的样品精确定位、扫描和重复定位。",
  "description_en": "The MC2000 is a motion controller for a motorized microscope stage or multi-axis translation stage, typically supporting X/Y/Z position readback, moves to target positions, and joystick-based manual control. In the lab it is used for precise sample positioning, scanning, and reproducible repositioning during microscopy.",
  "actions": [
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到目标位置。",
      "description_en": "Move the specified channel to a target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取指定通道的当前位置。",
      "description_en": "Get the current position of the specified channel."
    },
    {
      "action_name": "auto-GetId",
      "description": "获取设备标识信息。",
      "description_en": "Get the device identification."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "获取控制器是否已准备好接收运动指令。",
      "description_en": "Get whether the controller is ready to accept motion commands."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取指定通道的对象信息。",
      "description_en": "Get object information for the specified channel."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取指定通道的相位或状态信息。",
      "description_en": "Get phase or state information for the specified channel."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置限制。",
      "description_en": "Get the minimum position limit of the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置限制。",
      "description_en": "Get the maximum position limit of the specified channel."
    },
    {
      "action_name": "auto-JoyOn",
      "description": "开启摇杆手动控制。",
      "description_en": "Enable joystick manual control."
    },
    {
      "action_name": "auto-JoyOff",
      "description": "关闭摇杆手动控制。",
      "description_en": "Disable joystick manual control."
    },
    {
      "action_name": "auto-addMenuItems",
      "description": "添加用于摇杆控制的菜单项和快捷键。",
      "description_en": "Add menu items and keyboard shortcuts for joystick control."
    }
  ],
  "tag_hints": [
    "motorized microscope stage",
    "XYZ positioning",
    "sample positioning",
    "joystick control",
    "microscopy automation",
    "translation stage"
  ]
}

